// ===== AYARLAR =====
const LIMIT = 20;   // her çalıştırmada kaç firma taransın
// ===================
const rows = $input.all().map(i => i.json)
  .filter(r => r.Status === 'needs_email' && r.Website)
  .sort((a, b) => Number(a.Rank) - Number(b.Rank))
  .slice(0, LIMIT);
const domainOf = (url) => {
  try {
    const h = new URL(/^https?:/.test(url) ? url : 'https://' + url).hostname.toLowerCase().replace(/^www\./, '');
    const p = h.split('.');
    if (p.length >= 3 && p[p.length - 1] === 'tr' && ['com','org','net','gov','edu'].includes(p[p.length - 2])) return p.slice(-3).join('.');
    return p.slice(-2).join('.');
  } catch (e) { return ''; }
};
return rows.map(r => ({ json: { Company: r.Company, Website: r.Website, CareersUrl: r.CareersUrl || '', Domain: domainOf(r.Website) } }))
           .filter(i => i.json.Domain);

const PATHS = ['', '/iletisim', '/kariyer', '/contact', '/careers', '/insan-kaynaklari', '/bize-ulasin'];
const out = [];
for (const item of $input.all()) {
  const base = new URL(/^https?:/.test(item.json.Website) ? item.json.Website : 'https://' + item.json.Website).origin;
  const urls = new Set(PATHS.map(p => base + p));
  if (item.json.CareersUrl) urls.add(item.json.CareersUrl);
  for (const u of urls) out.push({ json: { Company: item.json.Company, Domain: item.json.Domain, url: u } });
}
return out;

const base = $('Select rows').all().map(i => i.json);
const urls = $('Build URLs').all();
const state = {};
base.forEach(b => state[b.Company] = { domain: b.Domain, fetched: 0, emails: new Set() });

const badTld = /\.(png|jpe?g|gif|svg|webp|css|js|ico|woff2?|pdf)$/i;
const rx = /[a-z0-9._%+\-]+@[a-z0-9\-]+(?:\.[a-z0-9\-]+)*\.[a-z]{2,}/gi;
$input.all().forEach((item, idx) => {
  const src = urls[item.pairedItem?.item ?? idx]?.json;
  if (!src || !state[src.Company]) return;
  let txt = typeof item.json.data === 'string' ? item.json.data : '';
  if (!txt) return;
  state[src.Company].fetched++;
  txt = txt.replace(/&#0*64;|&commat;|\[at\]|\(at\)/gi, '@').replace(/%40/g, '@');
  (txt.match(rx) || []).forEach(e => {
    e = e.toLowerCase();
    if (badTld.test(e)) return;
    const d = e.split('@')[1];
    if (d === state[src.Company].domain || d.endsWith('.' + state[src.Company].domain)) state[src.Company].emails.add(e);
  });
});

const hr = /^(ik|hr|kariyer|career|careers|insankaynaklari|insan\.kaynaklari|recruit|recruitment|talent|jobs|job|basvuru|staj|cv)/i;
const generic = /^(info|iletisim|contact|bilgi|hello|merhaba)/i;
return Object.entries(state).map(([Company, s]) => {
  const list = [...s.emails];
  const best = list.find(e => hr.test(e.split('@')[0])) || list.find(e => generic.test(e.split('@')[0]));
  return { json: {
    Company,
    Email: best || '',
    Status: best ? 'pending_review' : (s.fetched ? 'no_email_found' : 'fetch_failed')
  } };
});
